from pathlib import Path

path = Path('sqlglot/dialects/mysql.py')
text = path.read_text()
text = text.replace(
    '            "FROM_UNIXTIME": build_formatted_time(exp.UnixToTime, "mysql"),',
    '            "FORMAT": exp.NumberToStr.from_arg_list,\n            "FROM_UNIXTIME": build_formatted_time(exp.UnixToTime, "mysql"),',
    1,
)
text = text.replace(
    '            exp.NullSafeNEQ: lambda self, e: f"NOT {self.binary(e, \'<=>\')}",',
    '            exp.NullSafeNEQ: lambda self, e: f"NOT {self.binary(e, \'<=>\')}",\n            exp.NumberToStr: rename_func("FORMAT"),',
    1,
)
path.write_text(text)

path = Path('sqlglot/dialects/duckdb.py')
text = path.read_text()
needle = '''            return self.func(
                "REGEXP_EXTRACT", expression.this, expression.expression, group, params
            )
'''
replacement = needle + '''
        @unsupported_args("culture")
        def numbertostr_sql(self, expression: exp.NumberToStr) -> str:
            fmt = expression.args.get("format")
            if fmt and fmt.is_int:
                return self.func("FORMAT", f"'{{:,.{fmt.name}f}}'", expression.this)

            self.unsupported("Only integer formats are supported by NumberToStr")
            return self.function_fallback_sql(expression)
'''
if text.count(needle) != 1:
    raise RuntimeError(f'Expected one DuckDB insertion point, found {text.count(needle)}')
path.write_text(text.replace(needle, replacement, 1))

path = Path('tests/dialects/test_mysql.py')
