text = text.replace(
    'from sqlglot import expressions as exp',
    'from sqlglot import UnsupportedError, expressions as exp',
    1,
)
text += '''

    def test_number_format(self):
        self.validate_all(
            "SELECT FORMAT(12332.123456, 4)",
